function CDV.AfterVideo(fn)
    local n = 0
    local function wait()
        n = n + 1
        local playing = false
        pcall(function() playing = TEN.View.IsVideoPlaying() end)
        if n < 15 or (playing and n < 30 * 150) then CDV.After(1, wait); return end
        fn()
    end
    CDV.After(1, wait)
end
