-- The gate of the courtyard: five small switches on the wall, numbered 1 to 5. The computer in the workshop shows
-- 33 2D 32 2D 35 (ASCII in hexadecimal): the gate opens with 2, 3 and 5 on and 1 and 4 off.
local GATE_CODE = { false, true, true, false, true }
local function GateOpen()
    CDV.Flag("cancello_aperto", true)
    CDV.GateSound()
    CDV.Swing("cancello_cortile", "y", 90, 50)
    CDV.After(32, function()          -- the passage is free when the gate is three quarters open
        CDV.Enable("blocco_cancello")
        local m = CDV.M("blocco_cancello")
        if m ~= nil and m:GetValid() then pcall(function() m:SetCollidable(false) end) end
        CDV.Log("GATE free")
    end)
end
CDV.Loop(function()
    if CDV.Flag("cancello_aperto") then return end
    local busy = SWITCH_STATES[Lara:GetState()] or SWITCH_ANIMS[Lara:GetAnim()]
    local ok = true
    for i = 1, 5 do
        if CDV.Used("int_" .. i) then CDV.Flag("int_t", 50) end          -- judge when Lara has finished with the switch
        if CDV.Pulled("int_" .. i) ~= GATE_CODE[i] then ok = false end   -- where the lever really is
    end
    local t = CDV.Flag("int_t") or 0
    if t > 0 then
        t = t - 1
        CDV.Flag("int_t", t)
    end
    if t > 0 or busy then return end
    -- a switch that has been used is set free again, so that a second Action pulls it back
    for i = 1, 5 do
        local m = CDV.M("int_" .. i)
        if m ~= nil and m:GetValid() then
            pcall(function()
                local free = TEN.Objects.MoveableStatus.INACTIVE
                if m:GetStatus() ~= free then
                    m:SetStatus(free)
                    CDV.Log("SWITCH " .. i .. " free, pulled " .. tostring(CDV.Pulled("int_" .. i)))
                end
            end)
        end
    end
    if ok then GateOpen() end
end)

